use nutbook_backend::core::{html_edit::read_formal_motion_document,motion_session::MotionSession};
fn main(){let args:Vec<_>=std::env::args().collect();let source=std::fs::read_to_string(&args[1]).unwrap();let reports:Vec<serde_json::Value>=serde_json::from_str(&std::fs::read_to_string(&args[2]).unwrap()).unwrap();let mut session=MotionSession::new(read_formal_motion_document(&source).unwrap().unwrap());let mut results=Vec::new();for report in reports{let kind=report["type"].as_str().unwrap();let seq=report["sequence"].as_u64().unwrap_or(0);let generation=report["generation"].as_u64().unwrap_or(1);let state=report.get("motionState").filter(|v|!v.is_null()).map(|v|serde_json::from_value(v.clone()).unwrap());let accepted=match kind{"ready"|"page"=>{session.last_sequence=seq;session.ready(state.unwrap())},"begin"=>session.begin(seq),"begin-control"=>session.begin_control(seq,report["control"]["action"].as_str().unwrap(),report["control"]["timeMs"].as_f64()),"motion-planned"=>session.plan("motion-test",generation,seq,&state.unwrap()),"motion-applied"=>session.acknowledge("motion-test",generation,seq,state.unwrap()),"motion-state"=>if let Some(sample)=report["calibrationSequence"].as_u64(){session.calibrate_sample(seq,sample,state.unwrap())}else{session.calibrate(seq,state.unwrap())},"motion-page-request"=>session.request_page(seq,state.unwrap()),_=>continue};results.push(serde_json::json!({"type":kind,"accepted":accepted}));}println!("{}",serde_json::to_string(&results).unwrap());}
